#!/usr/bin/env bash
set -e
echo "Extrayendo el proyecto Boughazi TV (version corregida, sin PayPal)..."
TMP_B64=$(mktemp)
cat > "$TMP_B64" <<'BOUGHAZI_TV_BASE64_EOF'

BOUGHAZI_TV_BASE64_EOF
base64 -d "$TMP_B64" > boughazi-tv-native.tar.gz
rm -f "$TMP_B64"
tar -xzf boughazi-tv-native.tar.gz
rm -f boughazi-tv-native.tar.gz
echo "Listo. La carpeta boughazi-tv-native/ contiene el proyecto completo, con .github incluido."
echo "Copia (o mueve) TODO su contenido a la raiz de tu repositorio y sube los cambios."
